"""Pure append-only repair contract; API and cryptographic verifier are injected.

A plan is an inventory, never authorization or proof. No production CLI exposes apply
until the workflow supplies the independently verified complete immutable bundle.
"""
from dataclasses import dataclass
import hashlib
import json
import re

from release_evidence_assets import expected_release_assets


# New repair lane supports JSON/signature members up to 8 MiB, never layers/JARs.
MAX_REPAIR_MEMBER = 8 * 1024 * 1024


def require_member_size(size):
    if type(size) is not int or not 0 < size <= MAX_REPAIR_MEMBER:
        raise ValueError("member exceeds supported repair-lane size")


def identity(api, tag, commit, release_id, workflow_revision):
    if not tag or re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9._-]*', tag) is None:
        raise ValueError('invalid explicit tag')
    if any(re.fullmatch(r'[0-9a-f]{40}', x) is None for x in (commit, workflow_revision)):
        raise ValueError('immutable commit and workflow revision required')
    if type(release_id) is not int or release_id <= 0:
        raise ValueError('explicit release ID required')
    release = api.release(tag)
    if release['id'] != release_id or release['tag_name'] != tag or api.tag_commit(tag) != commit:
        raise ValueError('release identity changed')
    return release


def assets_by_name(api, release_id):
    result = {}
    for asset in api.assets(release_id):  # Adapter must enumerate every page.
        if asset['name'] in result:
            raise ValueError('duplicate release asset')
        result[asset['name']] = asset
    return result


def plan(api, *, tag, commit, release_id, workflow_revision):
    identity(api, tag, commit, release_id, workflow_revision)
    if assets_by_name(api, release_id):
        raise ValueError('zero-asset repair refuses existing assets')
    return dict(schemaVersion=1, tag=tag, commit=commit, release_id=release_id,
                workflow_revision=workflow_revision, originalAssets=[])


@dataclass(frozen=True)
class VerifiedBundle:
    """Receipt returned only by the production cryptographic verification adapter."""
    binding_sha256: str


def bind_bundle(repair, bundle, *, repository, producer_run_id, producer_run_attempt):
    """Persist this exact binding with the bundle before apply or cross-run resume.

    This is not a signature or proof of trusted provenance; apply's verifier must
    authenticate the producer and all subjects against this immutable binding.
    """
    if (re.fullmatch(r'[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+', repository) is None
                or any(segment in ('.', '..') for segment in repository.split('/'))):
        raise ValueError('explicit repository required')
    if any(type(x) is not int or x <= 0 for x in (producer_run_id, producer_run_attempt)):
        raise ValueError('explicit producer run and attempt required')
    if set(bundle) != expected_release_assets(repair['tag']) or any(type(v) is not bytes or not v for v in bundle.values()):
        raise ValueError('complete nonempty nine-file bundle required')
    return repair | {'repository': repository, 'producerRunId': producer_run_id,
                     'producerRunAttempt': producer_run_attempt,
                     'sha256': {n: hashlib.sha256(b).hexdigest() for n, b in sorted(bundle.items())}}


def binding_digest(bound):
    return hashlib.sha256(json.dumps(bound, sort_keys=True, separators=(',', ':'), allow_nan=False).encode()).hexdigest()


def apply(api, repair, bundle, verify_complete_bundle, *, resume=False):
    """Verify all nine bytes before any POST; never delete, patch or clobber.

    verify_complete_bundle must perform actual signature/subject/producer validation.
    It must raise on any failure; a claimed verification field in a plan is not used.
    """
    if repair.get('schemaVersion') != 1 or type(repair.get('schemaVersion')) is not int or repair.get('originalAssets') != []:
        raise ValueError('invalid zero-asset plan')
    args = {k: repair[k] for k in ('tag', 'commit', 'release_id', 'workflow_revision')}
    if getattr(api, 'repository', None) != repair.get('repository'):
        raise ValueError('API repository differs from immutable binding')
    identity(api, **args)
    if set(bundle) != expected_release_assets(repair['tag']) or any(type(v) is not bytes or not v for v in bundle.values()):
        raise ValueError('complete nonempty nine-file bundle required')
    # Exact persisted hashes bind resumes to the original generated bytes, not a
    # timestamp-dependent regeneration that happens to target the same release.
    expected = bind_bundle({k: repair[k] for k in ('schemaVersion', 'tag', 'commit', 'release_id', 'workflow_revision', 'originalAssets')},
                           bundle, repository=repair['repository'],
                           producer_run_id=repair['producerRunId'], producer_run_attempt=repair['producerRunAttempt'])
    if repair != expected:
        raise ValueError('persisted bundle binding mismatch')
    bundle = dict(bundle)
    digest = binding_digest(repair)
    receipt = verify_complete_bundle(json.loads(json.dumps(repair)), bundle.copy())
    if type(receipt) is not VerifiedBundle or receipt.binding_sha256 != digest:
        raise ValueError('explicit cryptographic verification receipt required')
    existing = assets_by_name(api, repair['release_id'])
    if existing and not resume:
        raise ValueError('zero-asset plan no longer empty')
    if set(existing) - set(bundle):
        raise ValueError('unexpected existing asset')
    for name, asset in existing.items():
        if api.download(asset['id'], len(bundle[name])) != bundle[name]:
            raise ValueError('existing asset bytes differ')
    def checked_inventory():
        observed = assets_by_name(api, repair['release_id'])
        if set(observed) - set(bundle) or any(api.download(a['id'], len(bundle[n])) != bundle[n] for n, a in observed.items()):
            raise ValueError('existing asset bytes differ')
        return observed

    for name in sorted(bundle):
        identity(api, **args)
        existing = checked_inventory()
        if name not in existing:
            # Includes HTTP422 and ambiguous network outcomes: never assume success.
            try:
                api.upload(repair['release_id'], name, bundle[name])
            except (OSError, TimeoutError):
                pass
        observed = checked_inventory()
        if name not in observed:
            raise ValueError('upload outcome does not match immutable bundle')
    identity(api, **args)
    observed = assets_by_name(api, repair['release_id'])
    if set(observed) != set(bundle) or any(api.download(observed[n]['id'], len(b)) != b for n, b in bundle.items()):
        raise ValueError('committed bundle readback mismatch')
    return {n: hashlib.sha256(b).hexdigest() for n, b in bundle.items()}
